{
    'nodes': [{
        'id': 't0-rgd',
        'name': 'T0 Constraints',
        'type': 'decisionTable',
        'content': {
            'hitPolicy': 'collect',
            'inputs': [
                {'id': 'width',          'name': 'width'},
                {'id': 'height',         'name': 'height'},
                {'id': 'has_wicket_door','name': 'has_wicket_door'},
                {'id': 'guide_type',     'name': 'guide_type'}
            ],
            'outputs': [
                {'id': 'level',   'name': 'level'},
                {'id': 'message', 'name': 'message'}
            ],
            'rules': [
                {
                    'width':           '0',
                    'height':          '',
                    'has_wicket_door': '',
                    'guide_type':      '',
                    'level':   '"error"',
                    'message': '"Opening width must be greater than 0 mm."'
                },
                {
                    'width':           '',
                    'height':          '0',
                    'has_wicket_door': '',
                    'guide_type':      '',
                    'level':   '"error"',
                    'message': '"Opening height must be greater than 0 mm."'
                },
                {
                    'width':           '< 1500',
                    'height':          '',
                    'has_wicket_door': '',
                    'guide_type':      '',
                    'level':   '"error"',
                    'message': '"Width must be at least 1500 mm for a garage door."'
                },
                {
                    'width':           '> 6000',
                    'height':          '',
                    'has_wicket_door': '',
                    'guide_type':      '',
                    'level':   '"error"',
                    'message': '"Width exceeds maximum production range (6000 mm)."'
                },
                {
                    'width':           '',
                    'height':          '< 1800',
                    'has_wicket_door': '',
                    'guide_type':      '',
                    'level':   '"error"',
                    'message': '"Height must be at least 1800 mm for a garage door."'
                },
                {
                    'width':           '',
                    'height':          '> 3500',
                    'has_wicket_door': '',
                    'guide_type':      '',
                    'level':   '"error"',
                    'message': '"Height exceeds maximum production range (3500 mm)."'
                },
                {
                    'width':           '< 2500',
                    'height':          '',
                    'has_wicket_door': 'true',
                    'guide_type':      '',
                    'level':   '"error"',
                    'message': '"Wicket door requires opening width of at least 2500 mm."'
                },
                {
                    'width':           '',
                    'height':          '< 2000',
                    'has_wicket_door': 'true',
                    'guide_type':      '',
                    'level':   '"error"',
                    'message': '"Wicket door requires opening height of at least 2000 mm."'
                },
                {
                    'width':           '> 4500',
                    'height':          '',
                    'has_wicket_door': '',
                    'guide_type':      '"standard"',
                    'level':   '"warning"',
                    'message': '"Width > 4500 mm: heavy-duty C-guides are recommended."'
                }
            ]
        }
    }]
}

